pub fn classify(n: i32) i32 {
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    } else if (n == 2) {
        return 2;
    } else if (n == 3) {
        return 3;
    } else if (n == 4) {
        return 4;
    } else if (n == 5) {
        return 5;
    } else if (n == 6) {
        return 6;
    } else if (n == 7) {
        return 7;
    } else if (n == 8) {
        return 8;
    } else {
        return 9;
    }
}
